<?php $lastSaved=$lastSaved??null;$richStored=array_values(array_filter($record['credits']??[],static fn($c)=>!empty($c['relation_key'])));$storedContext=count(array_filter($richStored,static fn($c)=>\App\Services\Metadata\MusicBrainzCreditGraph::isContext($c['relation']??json_decode($c['relation_json'],true))));$storedCredits=count($richStored)-$storedContext; ?>
<?php if($lastSaved): ?><section class="card" id="last-saved-credits"><h2>Última actualización guardada</h2><p>Los créditos de esta actualización siguen guardados. Una consulta nueva o su cancelación no los elimina.</p><p><strong><?= $storedCredits ?> créditos musicales importados</strong> · <?= $storedContext ?> relaciones de contexto conservadas, sin contarlas como participantes.</p><?php if(!empty($lastSaved['state']['applied_at'])): ?><p>Guardado: <?= e($lastSaved['state']['applied_at']) ?> (UTC).</p><?php endif; ?></section><?php endif; ?>
<?php if($lastSaved&&$job&&$job['id']!==$lastSaved['id']&&$job['status']==='collecting'&&empty($s['calls'])): ?><p class="card" id="new-credit-query">Esta es una consulta nueva, sin peticiones a MusicBrainz. No es un reinicio ni una pérdida de la actualización guardada.</p><?php endif; ?>
<?php if($error): ?><p class="alert" role="alert"><?= e($error) ?></p><?php endif; ?>
